requireMatch('formation named-window serialization', formation, /pg_advisory_xact_lock\s*\(/i, 'same hard Signal identity must serialize before group selection')
requireMatch('formation capacity row revalidation', formation, /limit\s+1\s+for update/i, 'selected accepting group must be locked before delegation')
requireMatch('assigned retry bypass precedes named-window lock', assignedRetryFastPath, /ASSIGNED-USER RETRY FAST PATH[\s\S]*?for share of si, sgm, sg;[\s\S]*?return;[\s\S]*?NAMED-WINDOW CONCURRENCY LOCK/i, 'already-assigned retries must return before entering first-time formation serialization')
requireMatch('assigned retry protects authoritative rows', assignedRetryFastPath, /for share of si, sgm, sg;/i, 'retry fast path must prevent concurrent withdrawal or group mutation while returning authority')
requireMatch('block-safe formation serialization', blockSafeFormation, /pg_advisory_xact_lock\s*\(/i, 'latest block-safe formation authority must preserve hard-identity serialization')
requireMatch('single live journey uniqueness', singleJourney, /create unique index if not exists signal_intents_one_assigned_per_user_idx/i, 'database must reject two assigned Signal intents for one user')
requireMatch('Signal core uses private data-free invalidation', signalCoreRealtime, /broadcast_signal_core_refresh[\s\S]*?jsonb_build_object\('changed',true\)[\s\S]*?'signal:'[\s\S]*?true\)[\s\S]*?drop table public\.signal_intents[\s\S]*?drop table public\.signal_groups[\s\S]*?drop table public\.signal_group_memberships/i, 'Signal formation and journey state must not fan out through per-subscriber Postgres Changes')
requireMatch('Signal core private topic is group-member authorized', signalCoreRealtime, /signal_group_broadcast_receive[\s\S]*?is_signal_group_member/i, 'Signal journey invalidations must remain private to matched or confirmed group members')
requireMatch('Signal core client joins authenticated private topic', signalCoreRealtimeClient, /realtime\.setAuth\(\)[\s\S]*?signal:\$\{target\.signalGroupId\}[\s\S]*?private: true[\s\S]*?\.on\([\s\S]*?'broadcast'/i, 'Signal journey client must consume the private group broadcast authority')
requireMatch('confirmation canonical group lock', confirmation, /signal_groups[\s\S]{0,500}for update/i, 'confirmation must serialize on the authoritative Signal group')
requireMatch('conversion group row lock', conversion, /signal_groups[\s\S]{0,500}for update/i, 'Signal-to-Plan conversion must serialize on the Signal group')
requireMatch('conversion retry idempotency', conversion, /originating_signal_group_id/i, 'Signal-origin Plan identity must be stable across retries')
requireMatch('plan message retry dedupe', messageRepair, /on conflict do nothing/i, 'message retry must not create duplicate message rows')
requireMatch('Plan messages use private data-free invalidation', planMessagingRealtime, /broadcast_plan_message_refresh[\s\S]*?jsonb_build_object\('changed',true\)[\s\S]*?'messages:'[\s\S]*?true\)[\s\S]*?drop table public\.messages/i, 'group message rows must not fan out through Postgres Changes')
requireMatch('Plan message and typing topics require open membership', planMessagingRealtime, /can_access_plan_conversation_realtime_topic[\s\S]*?conversation_membership_intervals[\s\S]*?ended_at is null[\s\S]*?plan_conversation_broadcast_receive[\s\S]*?plan_typing_broadcast_send/i, 'group chat refresh and typing must remain private to current conversation members')
requireMatch('Plan message and typing clients use authenticated private channels', planMessagingRealtimeClient, /realtime\.setAuth\(\)[\s\S]*?messages:\$\{normalizedConversationId\}[\s\S]*?private: true[\s\S]*?realtime\.setAuth\(\)[\s\S]*?plan-typing:\$\{conversationId\}[\s\S]*?private: true/i, 'group message refresh and typing must join authorized private Realtime topics')
requireMatch('legacy non-idempotent sends retired', messageRetirement, /Legacy non-idempotent send retained for migration history only/i, 'browser callers must not use legacy message mutation')
requireMatch('notification user dedupe key', notifications, /notifications_user_dedupe_key/i, 'replayed domain events must not duplicate user notifications')
requireMatch('notifications use data-free private realtime invalidation', notificationRealtime, /jsonb_build_object\('changed',true\)[\s\S]*?'notifications:'[\s\S]*?true\)[\s\S]*?drop table public\.notifications/i, 'notification invalidations must avoid per-subscriber Postgres Changes authorization and expose no notification payload')
requireMatch('notification private topic is owner-authorized', notificationRealtime, /notifications_broadcast_receive[\s\S]*?extension='broadcast'[\s\S]*?auth\.uid\(\)/i, 'notification private topics must only be readable by the matching authenticated owner')
