requireMatch('signal connections private topic is user-authorized', signalConnectionsRealtime, /signal_connections_broadcast_receive[\s\S]*?extension='broadcast'[\s\S]*?auth\.uid\(\)/i, 'private connection topics must only be readable by the matching authenticated user')
