requireMatch('journey resume excludes withdrawn Plan members', journeyResumeOutingAuthority, /where pm\.user_id=v_user_id[\s\S]*?pm\.membership_state='active'::public\.plan_membership_state[\s\S]*?p\.state not in \('cancelled'::public\.plan_state,'completed'::public\.plan_state\)/i, 'a user who leaves a converted Plan must be absent from canonical journey resume even if the originating Signal group still exists')
requireMatch('journey resume requires explicit self check-in', journeyResumeOutingAuthority, /select min\(ar\.occurred_at\)[\s\S]*?ar\.plan_id=p\.id and ar\.user_id=v_user_id[\s\S]*?ar\.evidence_type='self_reported'::public\.attendance_evidence_type/i, 'verified or partner-supported attendance must never impersonate the caller pressing I AM HERE')
requireMatch('attendance status requires explicit self check-in', explicitAttendanceStatus, /select min\(ar\.occurred_at\)[\s\S]*?ar\.user_id=v_user_id[\s\S]*?ar\.evidence_type='self_reported'::public\.attendance_evidence_type[\s\S]*?count\(distinct ar\.user_id\)[\s\S]*?ar\.evidence_type='self_reported'::public\.attendance_evidence_type/i, 'live attendance UI and HERE counts must use the same explicit self-report authority as canonical journey resume')
requireMatch('live Plan uses data-free realtime invalidation', livePlanRefreshBroadcast, /realtime\.send\(jsonb_build_object\('source',tg_table_name\),'refresh',v_topic,false\)[\s\S]*?attendance_live_plan_refresh[\s\S]*?completion_live_plan_refresh[\s\S]*?plan_state_live_plan_refresh/i, 'check-in, DONE HERE, and Plan lifecycle changes must wake peers without exposing attendance/completion rows')
requireMatch('residual anonymous function ACL closed', residualAnonAcl, /get_my_chill_dating_preferences\(\) from anon[\s\S]*?update_my_chill_dating_preferences[\s\S]*?from anon[\s\S]*?get_my_signal_discovery_realtime_topic\(\) from anon[\s\S]*?sync_signal_journey_stage\(\) from public,anon,authenticated/i, 'auth-only preference/topic RPCs and internal trigger functions must not retain browser-anonymous execution grants')
requireMatch('Signal arrival notifies active peers idempotently', signalArrivalPeerAwareness, /evidence_type <> 'self_reported'[\s\S]*?signal_member_arrived[\s\S]*?pm\.membership_state='active'[\s\S]*?pm\.user_id<>new\.user_id[\s\S]*?on conflict \(user_id,dedupe_key\)[\s\S]*?do nothing/i, "an explicit I'M HERE must notify each other active Plan member once without self-notifying or duplicating on retry")
