requireMatch('completion survey requires private feedback before exit', signalCompletionView, /disabled=\{!rating \|\| saving\}[\s\S]*?CHOOSE ONE TO FINISH/i, 'the completion survey must not be skipped before a private experience response is saved')
requireMatch('completion survey is deployment-stable in app shell', appShell, /import SignalCompletionView from '\.\/features\/outing\/SignalCompletionView'[\s\S]*?getMyPendingSignalCompletionPlanId\(\)[\s\S]*?completionHandoffRef\.current = true[\s\S]*?setCompletionPlanId\(planId\)/i, 'the critical DONE HERE handoff must not depend on a stale lazy chunk and must restore unfinished completion from server authority')
requireMatch('completed Signal releases active core memberships', completedSignalMembershipClosure, /state='completed'::public\.signal_group_state[\s\S]*?update public\.signal_group_memberships[\s\S]*?is_active_core=false[\s\S]*?ended_at=coalesce\(ended_at,v_now\)[\s\S]*?signal_group_id=v_plan\.originating_signal_group_id/i, 'Plan lifecycle completion must retire active-core Signal memberships instead of leaving historical groups looking live')
