requireMatch('All Signal exit boundaries invalidate in-flight restore', appShell, /await withdrawMySignal\(signalIntentId\)[\s\S]*?journeyRestoreEpochRef\.current \+= 1[\s\S]*?journeyRestorePromiseRef\.current = null[\s\S]*?onOutingEnded=\{\(reason\) => \{[\s\S]*?journeyRestoreEpochRef\.current \+= 1[\s\S]*?journeyRestorePromiseRef\.current = null[\s\S]*?onPlanEnded=\{\(\) => \{[\s\S]*?journeyRestoreEpochRef\.current \+= 1[\s\S]*?journeyRestorePromiseRef\.current = null/i, 'pre-conversion leave, live outing exit, and converted Plan leave must invalidate older resume responses and release the stale in-flight promise immediately')
requireMatch('Logout invalidates in-flight journey restore', appShell, /const handleLogout = async \(\) => \{[\s\S]*?journeyRestoreEpochRef\.current \+= 1[\s\S]*?journeyRestorePromiseRef\.current = null[\s\S]*?await signOutCurrentUser\(\)/i, 'sign-out must sever any pending journey restore so a different account is never deduplicated against the previous account request')
requireMatch('Check-in invalidates pre-arrival journey restore', appShell, /onCheckedIn=\{\(\) => \{[\s\S]*?journeyRestoreEpochRef\.current \+= 1[\s\S]*?journeyRestorePromiseRef\.current = null[\s\S]*?restoreActiveSignal\(true\)/i, 'successful arrival must not be deduplicated against a restore request that began before attendance committed')

const failures = checks.filter((check) => !check.ok)
for (const check of checks) console.log(`${check.ok ? 'PASS' : 'FAIL'}  ${check.name}`)
if (failures.length) {
  console.error('\nConcurrency contract verification failed:')
  failures.forEach((check) => console.error(`- ${check.name}: ${check.reason}`))
  process.exitCode = 1
} else {
  console.log(`\nConcurrency contract verification passed (${checks.length}/${checks.length}).`)
}
